// Literal epoch-day expectations, not generated by time.Date or the runtime.
// Timestamp text is parsed only to specify the input instant.
var dateZoneCases = []struct {
	zone, instant string
	ns            int64
	day           int32
}{
	{"utc", "", -1, -1}, {"utc", "", math.MinInt64, -106752}, {"utc", "", math.MaxInt64, 106751},
	{"utc", "1970-01-01T00:00:00Z", 0, 0},
	{"new_york", "2024-03-10T06:59:59.999999999Z", 0, 19792}, {"new_york", "2024-03-10T07:00:00Z", 0, 19792},
	{"new_york", "2024-11-03T05:59:59.999999999Z", 0, 20030}, {"new_york", "2024-11-03T06:00:00Z", 0, 20030},
	{"new_york", "2024-03-01T04:59:59.999999999Z", 0, 19782}, {"new_york", "2024-03-01T05:00:00Z", 0, 19783},
	{"new_york", "2024-01-01T04:59:59Z", 0, 19722}, {"new_york", "2024-01-01T05:00:00Z", 0, 19723},
	{"lord_howe", "2024-04-06T14:59:59Z", 0, 19820}, {"lord_howe", "2024-04-06T15:00:00Z", 0, 19820},
	{"lord_howe", "2024-10-05T15:29:59Z", 0, 20002}, {"lord_howe", "2024-10-05T15:30:00Z", 0, 20002},
	{"apia", "2011-12-30T09:59:59Z", 0, 15337}, {"apia", "2011-12-30T10:00:00Z", 0, 15339},
	{"paris", "1899-12-31T23:50:38.999999999Z", 0, -25568}, {"paris", "1899-12-31T23:50:39Z", 0, -25567},
}

func dateZoneBatch(n int, ns int64) *memory.Batch {
	b := memory.NewBatch()
	b.Rows = n
	v := &memory.Int64Vector{Values: make([]int64, n), Validity: make(memory.Bitmap, memory.WordsFor(n))}
	for i := range v.Values {
		v.Values[i] = ns
		if i%7 != 0 {
			memory.Set(v.Validity, i)
		} else {
			v.Values[i] = math.MaxInt64
		}
	}
	b.Int64s["ts"] = v
	return b
}
func dateZoneSchema() memory.Schema {
	return memory.NewSchema(memory.Field{Name: "ts", Type: memory.TypeTimestamp, Nullable: true})
}
func TestDateInZoneHardcodedCalendar(t *testing.T) {
	for _, tc := range dateZoneCases {
		t.Run(fmt.Sprintf("%s/%s/%d", tc.zone, tc.instant, tc.ns), func(t *testing.T) {
			z := timezoneFixture(t, tc.zone)
			p, err := Compile(dateZoneSchema(), DateInZone(Col("ts"), z))
			if err != nil {
				t.Fatal(err)
			}
			if !p.SupportsSelection() {
				t.Fatal("selection unsupported")
			}
			if p.ResultField().Type != memory.TypeDate32 || !p.ResultField().Nullable {
				t.Fatal("Date32 metadata")
			}
			ns := timezoneNanos(t, timezoneCase{zone: tc.zone, instant: tc.instant, ns: tc.ns})
			m := memory.NewBudgetManager(0)
			w, _ := NewWorkspace(context.Background(), p, m)
			for _, n := range []int{0, 1, 63, 64, 65, 130, 1} {
				b := dateZoneBatch(n, ns)
				original := append([]int64(nil), b.Int64s["ts"].Values...)
				for _, selected := range []bool{false, true} {
					rows := []int{}
					for i := 0; i < n; i += 2 {
						rows = append(rows, i)
					}
					var out []ScalarValue
					if selected {
						out, err = w.EvaluateSelected(context.Background(), b, rows, testKernelSet())
					} else {
						out, err = w.Evaluate(context.Background(), b, testKernelSet())
					}
					if err != nil {
						t.Fatal(err)
					}
					count := n
					if selected {
						count = len(rows)
					}
					for i := 0; i < count; i++ {
						r := i
						if selected {
							r = rows[i]
						}
						valid := r%7 != 0
						v := out[0].Int32
						if v.IsValid(i) != valid {
							t.Fatal("NULL", r)
						}
						want := int32(0)
						if valid {
							want = tc.day
						}
						if v.Values[i] != want {
							t.Fatalf("row%d got%d want%d", r, v.Values[i], want)
						}
					}
				}
				if !reflect.DeepEqual(original, b.Int64s["ts"].Values) && n > 0 {
					t.Fatal("input mutation")
				}
				if m.Used() != w.MemoryBytes() {
					t.Fatal("accounting")
				}
			}
			w.Close()
			if m.Used() != 0 {
				t.Fatal("leak")
			}
		})
	}
}
func TestDateInZoneExtremeOffsetAndIdentity(t *testing.T) {
	for _, tc := range []struct {
		off  int32
		ns   int64
		want int32
	}{{math.MinInt32, math.MinInt64, -131608}, {math.MaxInt32, math.MinInt64, -81897}, {math.MinInt32, math.MaxInt64, 81896}, {math.MaxInt32, math.MaxInt64, 131607}, {math.MinInt32, 0, -24856}, {math.MaxInt32, 0, 24855}} {
		z, e := TimeZoneFromTZData("extreme", timezoneFixedData(tc.off))
		if e != nil {
			t.Fatal(e)
		}
		p, e := Compile(dateZoneSchema(), DateInZone(Col("ts"), z))
		if e != nil {
			t.Fatal(e)
		}
		w, _ := NewWorkspace(context.Background(), p, nil)
		out, e := w.Evaluate(context.Background(), dateZoneBatch(2, tc.ns), testKernelSet())
		if e != nil || out[0].Int32.Values[1] != tc.want {
			t.Fatal(tc, e, out)
		}
		w.Close()
	}
	a, _ := TimeZoneFromTZData("same", timezoneFixedData(-3600))
	b, _ := TimeZoneFromTZData("same", timezoneFixedData(3600))
	c, _ := TimeZoneFromTZData("same", timezoneFixedData(-3600))
	p, e := CompileExpressions(dateZoneSchema(), []NamedExpr{Named(DateInZone(Col("ts"), a), "a"), Named(DateInZone(Col("ts"), a), "same"), Named(DateInZone(Col("ts"), b), "other"), Named(DateInZone(Col("ts"), c), "reload"), Named(DayInZone(Col("ts"), a), "daypart")})
	if e != nil {
		t.Fatal(e)
	}
	if p.outputs[0].root != p.outputs[1].root {
		t.Fatal("same handle CSE")
	}
	for _, j := range []int{2, 3, 4} {
		if p.outputs[0].root == p.outputs[j].root {
			t.Fatal("merged distinct identity/operation")
		}
	}
	w, _ := NewWorkspace(context.Background(), p, nil)
	out, e := w.Evaluate(context.Background(), dateZoneBatch(2, 0), testKernelSet())
	if e != nil {
		t.Fatal(e)
	}
	for i, want := range []int32{-1, -1, 0, -1} {
		if out[i].Int32.Values[1] != want {
			t.Fatal("same name distinct rules")
		}
	}
	w.Close()
}
func TestDateInZoneBindingGuardsAndUTC(t *testing.T) {
	z := timezoneFixture(t, "utc")
	schema := dateZoneSchema()
	bound, e := Bind(schema, DateInZone(Col("ts"), z))
	if e != nil || bound.MayError || !reflect.DeepEqual(Columns(bound.Expr), []string{"ts"}) {
		t.Fatal("binding", e)
	}
	for _, x := range []Expr{DateInZone(Col("ts"), TimeZone{}), DateInZone(I64(1), z), DateInZone(Str("bad"), z), If(Bool(false), DateInZone(Col("ts"), TimeZone{}), CastTo(I64(0), memory.TypeDate32))} {
		if _, err := Compile(schema, x); err == nil {
			t.Fatal("invalid bind accepted")
		}
	}
	bad := DateInZone(CastTo(Str("bad"), memory.TypeTimestamp), z)
	good := DateInZone(Col("ts"), z)
	for name, x := range map[string]Expr{"if": If(Bool(false), bad, good), "case": Case([]WhenThen{{When: Bool(false), Then: bad}}, good), "coalesce": Coalesce(good, bad)} {
		t.Run(name, func(t *testing.T) {
			p, err := Compile(schema, x)
			if err != nil {
				t.Fatal(err)
			}
			b := dateZoneBatch(2, -1)
			b.Int64s["ts"].Validity = nil
			b.Int64s["ts"].Values[0] = -1
			w, _ := NewWorkspace(context.Background(), p, nil)
			out, err := w.Evaluate(context.Background(), b, testKernelSet())
			if err != nil || out[0].Int32.Values[0] != -1 || out[0].Int32.Values[1] != -1 {
				t.Fatal(err)
			}
			w.Close()
		})
	}
	p, err := Compile(schema, bad)
	if err != nil {
		t.Fatal(err)
	}
	w, _ := NewWorkspace(context.Background(), p, nil)
	if _, err = w.Evaluate(context.Background(), dateZoneBatch(2, -1), testKernelSet()); err == nil {
		t.Fatal("active fallible child did not fail")
	}
	w.Close()
	p, err = Compile(schema, CastTo(Col("ts"), memory.TypeDate32))
	if err != nil {
		t.Fatal(err)
	}
	w, _ = NewWorkspace(context.Background(), p, nil)
	for _, tc := range []struct {
		ns  int64
		day int32
	}{{-1, -1}, {math.MinInt64, -106752}, {math.MaxInt64, 106751}} {
		out, err := w.Evaluate(context.Background(), dateZoneBatch(2, tc.ns), testKernelSet())
		if err != nil || out[0].Int32.Values[1] != tc.day {
			t.Fatal("old UTC cast changed", err)
		}
	}
	w.Close()
}

type dateZoneCancelContext struct {
	context.Context
	cancel       context.CancelFunc
	checks, stop int
}

func (c *dateZoneCancelContext) Err() error {
	var pcs [24]uintptr
	n := runtime.Callers(2, pcs[:])
	frames := runtime.CallersFrames(pcs[:n])
	for {
		f, more := frames.Next()
		if strings.HasSuffix(f.Function, ".evalDateInZone") {
			c.checks++
			if c.checks == c.stop {
				c.cancel()
			}
			break
		}
		if !more {
			break
		}
	}
	return c.Context.Err()
}
func TestDateInZoneBudgetAndCancellation(t *testing.T) {
	p, e := Compile(dateZoneSchema(), DateInZone(Col("ts"), timezoneFixture(t, "new_york")))
	if e != nil {
		t.Fatal(e)
	}
	b := dateZoneBatch(193, -1)
	probe := &selectedFaultManager{Manager: memory.NewBudgetManager(0)}
	w, _ := NewWorkspace(context.Background(), p, probe)
	if _, e = w.Evaluate(context.Background(), b, testKernelSet()); e != nil {
		t.Fatal(e)
	}
	calls := probe.calls
	w.Close()
	for fail := 1; fail <= calls; fail++ {
		m := &selectedFaultManager{Manager: memory.NewBudgetManager(0), fail: fail}
		w, _ := NewWorkspace(context.Background(), p, m)
		if _, e = w.Evaluate(context.Background(), b, testKernelSet()); !errors.Is(e, memory.ErrBudgetExceeded) {
			t.Fatal(fail, e)
		}
		m.fail = 0
		out, e := w.Evaluate(context.Background(), b, testKernelSet())
		if e != nil || out[0].Int32.Values[1] != -1 {
			t.Fatal(e)
		}
		w.Close()
		if m.Used() != 0 {
			t.Fatal("budget leak")
		}
	}
	for _, stop := range []int{2, 3} {
		m := memory.NewBudgetManager(0)
		w, _ := NewWorkspace(context.Background(), p, m)
		base, cancel := context.WithCancel(context.Background())
		ctx := &dateZoneCancelContext{Context: base, cancel: cancel, stop: stop}
		_, e = w.Evaluate(ctx, b, testKernelSet())
		cancel()
		if !errors.Is(e, context.Canceled) || ctx.checks != stop {
			t.Fatal("running cancel", e, ctx.checks)
		}
		w.Close()
		if m.Used() != 0 {
			t.Fatal("cancel leak")
		}
	}
}

func TestDateInZoneDynamicGuardsAndCheckpoints(t *testing.T) {
	z := timezoneFixture(t, "utc")
	s := memory.NewSchema(memory.Field{Name: "s", Type: memory.TypeString}, memory.Field{Name: "keep", Type: memory.TypeBool}, memory.Field{Name: "first", Type: memory.TypeDate32, Nullable: true})
	b := memory.NewBatch()
	b.Rows = 3
	b.Strings["s"] = testStringVector([]string{"bad", "1970-01-01T00:00:00Z", "bad"}, nil)
	b.Uint32s["keep"] = &memory.Uint32Vector{Values: []uint32{0, 1, 0}}
	b.Int32s["first"] = &memory.Int32Vector{Values: []int32{0, 0, 0}, Validity: memory.Bitmap{5}}
	child := DateInZone(CastTo(Col("s"), memory.TypeTimestamp), z)
	zero := CastTo(I64(0), memory.TypeDate32)
	for name, x := range map[string]Expr{"if": If(Col("keep"), child, zero), "case": Case([]WhenThen{{When: Col("keep"), Then: child}}, zero), "coalesce": Coalesce(Col("first"), child)} {
		t.Run(name, func(t *testing.T) {
			p, e := Compile(s, x)
			if e != nil {
				t.Fatal(e)
			}
			w, _ := NewWorkspace(context.Background(), p, nil)
			for repeat := 0; repeat < 2; repeat++ {
				out, e := w.Evaluate(context.Background(), b, testKernelSet())
				if e != nil {
					t.Fatal(e)
				}
				for i := 0; i < 3; i++ {
					if !out[0].Int32.IsValid(i) || out[0].Int32.Values[i] != 0 {
						t.Fatal("dynamic domain", i)
					}
				}
			}
			w.Close()
		})
	}
	p, e := Compile(s, child)
	if e != nil {
		t.Fatal(e)
	}
	w, _ := NewWorkspace(context.Background(), p, nil)
	if _, e = w.Evaluate(context.Background(), b, testKernelSet()); e == nil || !strings.Contains(e.Error(), "cast") {
		t.Fatal("active parse control", e)
	}
	w.Close()
	for _, stop := range []int{2, 3} {
		const n = 193
		in := scalarRegister{typ: memory.TypeTimestamp, i64: make([]int64, n)}
		out := scalarRegister{typ: memory.TypeDate32, i32: make([]int32, n), ownedValidity: make(memory.Bitmap, memory.WordsFor(n))}
		for i := range in.i64 {
			in.i64[i] = -1
			out.i32[i] = -777
		}
		checks := 0
		out.checkContext = func() error {
			checks++
			if checks == stop {
				return context.Canceled
			}
			return nil
		}
		e := evalDateInZone(&out, &in, z.state, n)
		if !errors.Is(e, context.Canceled) || checks != stop {
			t.Fatal(e, checks)
		}
		for i, v := range out.i32 {
			want := int32(-777)
			if i < (stop-1)*64 {
				want = -1
			}
			if v != want {
				t.Fatal("cancel touched unprocessed slot", i, v)
			}
		}
	}
}

func TestDateInZonePOSIXFooterExtremeOffsets(t *testing.T) {
	// Go's accepted POSIX offset endpoint is 168:59:59. POSIX signs are
	// inverted from UTC offsets. Omitted DST offset adds one hour, so the
	// positive case reaches +169:59:59. The base TZif +01 differs from all
	// expectations: merely accepting but ignoring the footer cannot pass.
	for _, version := range []byte{0, '2', '3'} {
		for _, tc := range []struct {
			name, footer string
			ns           int64
			day          int32
			hour         int64
		}{
			{"east_standard", "<STD>-168:59:59", 2524608000000000000, 29227, 0},
			{"west_standard", "<STD>168:59:59", 2524608000000000000, 29212, 23},
			{"east_default_dst", "<STD>-168:59:59<DST>,M3.2.0,M11.1.0", 2540327400000000000, 29409, 0},
			{"west_default_dst", "<STD>168:59:59<DST>,M3.2.0,M11.1.0", 2540246400000000000, 29394, 0},
		} {
			t.Run(fmt.Sprintf("v%d/%s", version, tc.name), func(t *testing.T) {
				data := timezoneAbbreviationBlock(version, 1, []byte("FIX\x00"), 0)
				if version != 0 {
					data = append(data, timezoneAbbreviationBlock(version, 1, []byte("FIX\x00"), 0)...)
				}
				data = append(data, []byte("\n"+tc.footer+"\n")...)
				if len(data) > 256 {
					t.Fatal("fixture unexpectedly large")
				}
				z, err := TimeZoneFromTZData("footer-extreme", data)
				if err != nil {
					t.Fatal(err)
				}
				p, err := CompileExpressions(dateZoneSchema(), []NamedExpr{Named(DateInZone(Col("ts"), z), "date"), Named(HourInZone(Col("ts"), z), "hour")})
				if err != nil {
					t.Fatal(err)
				}
				w, _ := NewWorkspace(context.Background(), p, nil)
				defer w.Close()
				out, err := w.Evaluate(context.Background(), dateZoneBatch(2, tc.ns), testKernelSet())
				if err != nil {
					t.Fatal(err)
				}
				if out[0].Int32.Values[1] != tc.day || out[1].Int64.Values[1] != tc.hour {
					t.Fatalf("footer not applied: day%d hour%d expected%d/%d", out[0].Int32.Values[1], out[1].Int64.Values[1], tc.day, tc.hour)
				}
			})
		}
	}
}
